// Normalize actor output, filter by rating, remove duplicates, and cap the run.
const settings = $('Your settings (EDIT ME)').first().json;
const maxReviews = Math.min(25, Math.max(1, Number(settings.maxReviewsPerRun) || 25));
const maxStars = Math.min(5, Math.max(1, Number(settings.maxStarRating) || 3));
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  if (j.error) continue;
  const rating = Number(j.rating ?? j.stars ?? j.score ?? j.overallRating ?? 0);
  if (!rating || rating > maxStars) continue;
  const review = {
    source: j.source ?? j.site ?? (String(j.url ?? j.reviewUrl ?? '').toLowerCase().includes('capterra') ? 'Capterra' : 'G2'),
    reviewerName: j.reviewerName ?? j.author ?? j.user ?? j.reviewerFullName ?? 'Anonymous reviewer',
    reviewText: j.reviewText ?? j.text ?? j.comment ?? j.reviewBody ?? '',
    rating,
    reviewDate: j.reviewDate ?? j.date ?? j.publishedAt ?? '',
    reviewUrl: j.reviewUrl ?? j.url ?? j.permalink ?? '',
    competitorProductUrl: settings.competitorProductUrl,
    icpDescription: settings.icpDescription
  };
  const key = [review.reviewerName, review.reviewText].join('|').toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: review });
  if (out.length >= maxReviews) break;
}
if (out.length === 0) return [{ json: { _empty: true, note: 'No reviews matched the star-rating limit this run.' } }];
return out;

// Parse the AI response and create the final Google Sheets row.
const rows = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  let verdict = { score: 0, reason: 'AI call failed - inspect the execution log' };
  try {
    const content = j.choices?.[0]?.message?.content;
    if (content) verdict = JSON.parse(content);
  } catch (error) {
    verdict = { score: 0, reason: 'AI returned unparseable output - inspect the execution log' };
  }
  rows.push({ json: {
    processedAt: new Date().toISOString(),
    source: String(j.source ?? ''),
    reviewerName: String(j.reviewerName ?? 'Anonymous reviewer'),
    reviewText: String(j.reviewText ?? ''),
    rating: j.rating ?? '',
    reviewDate: String(j.reviewDate ?? ''),
    reviewUrl: String(j.reviewUrl ?? ''),
    competitorProductUrl: String(j.competitorProductUrl ?? ''),
    switchingIntentScore: Math.min(10, Math.max(0, Number(verdict.score) || 0)),
    reason: String(verdict.reason ?? '')
  } });
}
return rows;
